import socket, struct
# Try to guess the docker network: scan 172.31.0.0/24 for hosts with port 80 open (docker DNS IP is .11, gateway is .1, commons is .2)
import concurrent.futures
def check(ip):
    try:
        s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        s.settimeout(0.15)
        if s.connect_ex((ip, 80)) == 0:
            s.close()
            return ip
        s.close()
    except Exception:
        pass
    return None
with concurrent.futures.ThreadPoolExecutor(64) as ex:
    ips = [f"172.31.0.{i}" for i in range(1, 255) if i not in (1,2,11)]
    for fut in concurrent.futures.as_completed([ex.submit(check, ip) for ip in ips]):
        r = fut.result()
        if r: print("OPEN:", r)
print("done")
EOF"}

